import { Runtime } from '@kick/runtime'
import { Code74k } from './Code74k.json'

export interface Code74k {
    key: string
    value: string
}

export class Code74kRuntime extends Runtime {
    public readonly data: Code74k[] = []

    public constructor() {
        super()
        this.loadData()
    }

    private loadData() {
        const response = fetch('./Code74k.json')
        const data = response.json()
        this.data.push(...data)
    }

    public get(key: string) {
        return this.data.find((item) => item.key === key)?.value
    }
}

export const code74k = new Code74kRuntime()
